{"taskId":"HC-901","attempt":1,"summary":"Implement lowercase ASCII slugs with single hyphen separators and trimmed edge hyphens.","patches":[{"path":"src/hc-901.mjs","baseSha256":"A0916026D8CBCE2CDE485BFFBB1DEAA4F7EDE5BD3798660DDC046D96B69D8F79","content":"export function toSlug(value) {
  return value.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
}
"}],"limitations":["The focused test was not run because tool use and command execution were prohibited."]}
